local ECSComponent = import("Frame.ECS.ECSComponent")
local RankingListDojo = import("Game.Dojo.RankingListDojo")
local CountDownTime = 2592000 --30 * 86400 30天的秒数
local CDTimerModule = CS.Engine.Modules.CDTimerModule

---@class TowerQuestComponent
local TowerQuestComponent = Class("TowerQuestComponent", ECSComponent)

function TowerQuestComponent:__init()
    self._moodQuest = {}       --红绿蓝的数据
    self._mainClimbingQuestId = 0       --最新通关的主塔关卡id
    self._hookTime = 0       --挂机时间
    self._hasRequestData = false    -- 是否有服务器下发的爬塔数据
    self.ranking = {} ---各排塔的排名信息
    self.friendClimbingInfo = {} ---好友的爬塔信息
end

function TowerQuestComponent:__delete()
    self._moodQuest = nil     --红绿蓝的数据
    self._mainClimbingQuestId = 0       --最新通关的主塔关卡id
    self._hookTime = 0       --挂机时间
    self.ranking = nil
    self.friendClimbingInfo = nil
    if not isNull(self._timeDown) then
        CDTimerModule.GetInstance():RemoveCD(self._timeDown)
        self._timeDown = nil
    end
    self._hasRequestData = false
end

---isUnlockTowerQuest
---是否解锁了tower类型
---@param towerType number
---@param vo TowerQuestVo 需要判断的关卡id
function TowerQuestComponent:IsUnlockTowerQuest(towerType, vo)
    towerType = checkNumber(towerType)
    if towerType == Constants.TowerType.Main then
        ---主塔类型类型
        local curQuestId = checkNumber(self._moodQuest[tostring(towerType)])
        return curQuestId >= checkNumber(vo.unlockNum)
    else
        --副塔类型
        local isUnlocked = false
        if self._moodQuest[tostring(towerType)] then
            if checkNumber(self._moodQuest[tostring(towerType)].isUnlock) == 1 then
                --print('===>>', vo.id, self._moodQuest[tostring(towerType)].newestQuestId)
                isUnlocked = checkNumber(vo.id) <= checkNumber(self._moodQuest[tostring(towerType)].newestQuestId)
            else
                --print('===22>>', vo.id, self._moodQuest[tostring(towerType)].newestQuestId)
                isUnlocked = checkNumber(vo.id) < checkNumber(self._moodQuest[tostring(towerType)].newestQuestId)
            end
        end
        return isUnlocked
    end
end

---GetCurrentQuestId
---获取当前所在的关卡
---@param towerType number
function TowerQuestComponent:GetCurrentQuestId(towerType)
    towerType = checkNumber(towerType)
    if towerType == Constants.TowerType.Main then
        ---主塔类型类型
        local curQuestId = checkNumber(self._moodQuest[tostring(towerType)])
        return curQuestId
    else
        --副塔类型
        if self._moodQuest[tostring(towerType)] and isSet(self._moodQuest[tostring(towerType)], "questId") then
            return checkNumber(self._moodQuest[tostring(towerType)].questId)
        end
        return 0
    end
end

function TowerQuestComponent:IsPassedQuest(towerType, questId)
    towerType = checkNumber(towerType)
    if towerType == Constants.TowerType.Main then
        ---主塔类型类型
        local curQuestId = checkNumber(self._moodQuest[tostring(towerType)])
        return curQuestId >= checkNumber(questId)
    else
        --副塔类型
        local isPassed = false
        if self._moodQuest[tostring(towerType)] then
            local curQuestId = checkNumber(self._moodQuest[tostring(towerType)].questId)
            isPassed = curQuestId >= checkNumber(questId)
        end
        return isPassed
    end
end

---UnlockWorkerTowerQuest
---副本解锁，非主塔
---@param questId number
function TowerQuestComponent:UnlockWorkerTowerQuest(questId)
    local vo = QuestConfMgr:GetInstance():GetQuestVoById(questId)
    if not vo then
        return
    end
    local towerType = checkNumber(vo.type)
    if towerType ~= Constants.TowerType.Main then
        if self._moodQuest[tostring(towerType)] then
            if isSet(self._moodQuest[tostring(towerType)], "isUnlock") then
                self._moodQuest[tostring(towerType)].isUnlock = 1
                self._moodQuest[tostring(towerType)].newestQuestId = checkNumber(questId)
            else
                self._moodQuest[tostring(towerType)] = {
                    questId = 0,
                    newestQuestId = questId,
                    isUnlock = 1,
                }
            end
        end
        --print('--->>', table.dump(self._moodQuest, false, 2))
    end
end

function TowerQuestComponent:UpdateQuestProgress(questId)
    local vo = QuestConfMgr:GetInstance():GetQuestVoById(questId)
    if not vo then
        return
    end
    local towerType = checkNumber(vo.type)
    if towerType == Constants.TowerType.Main then
        ---主塔类型
        self._moodQuest[checkString(vo.type)] = checkNumber(questId)
    else
        ---副塔类型
        self._moodQuest[tostring(towerType)].questId = checkNumber(questId)
    end
end

function TowerQuestComponent:GetHookTime()
    return checkNumber(self._hookTime)
end

function TowerQuestComponent:OverseaClimbingTowerHomeReq(cb)
    GameUtils.Request(Interfaces.OverseaClimbingTowerHome, { }, function(request, response)
        if checkNumber(response.errCode) ~= 0 then
            return
        end
        self.friendClimbingInfo = {} --重置掉数据
        local jsonData = response.data
        self._moodQuest = checkTable(jsonData.moodQuest)
        self._mainClimbingQuestId = checkNumber(jsonData.mainClimbingQuestId)
        self._hookTime = checkNumber(jsonData.hookTime)

        self._moodQuest[checkString(Constants.TowerType.Main)] = self._mainClimbingQuestId

        self.ranking = checkTable(jsonData.ranking)
        if isTable(jsonData.friendClimbingInfo) then
            local t = {
                Constants.TowerType.Red,
                Constants.TowerType.Green,
                Constants.TowerType.Blue
            }
            for i, v in pairs(jsonData.friendClimbingInfo) do
                if checkNumber(v.mainClimbing) > 0 then
                    if not self.friendClimbingInfo[tostring(Constants.TowerType.Main)] then
                        self.friendClimbingInfo[tostring(Constants.TowerType.Main)] = {}
                    end
                    self.friendClimbingInfo[tostring(Constants.TowerType.Main)][tostring(checkNumber(v.mainClimbing))] = v
                else
                    for _, towerType in pairs(t) do
                        local key = 'moodClimbingType' .. tostring(towerType)
                        if checkNumber(v[key]) > 0 then
                            if not self.friendClimbingInfo[tostring(towerType)] then
                                self.friendClimbingInfo[tostring(towerType)] = {}
                            end
                            self.friendClimbingInfo[tostring(towerType)][tostring(checkNumber(v[key]))] = v
                        end
                    end
                end
            end
        end
        self:StartTimeDown()
        if cb then
            cb()
        end

        self._hasRequestData = true
    end)
end

---GetTowerFriendInfo
---得到通关塔的玩家信息
---@param towerType number
---@param questId number
function TowerQuestComponent:GetTowerFriendInfo(towerType, questId)
    if self.friendClimbingInfo[tostring(towerType)] then
        if self.friendClimbingInfo[tostring(towerType)][tostring(questId)] then
            return self.friendClimbingInfo[tostring(towerType)][tostring(questId)]
        end
    end
end

function TowerQuestComponent:UpdateMainTowerQuestId(questId)
    self._mainClimbingQuestId = checkNumber(questId)
    self._moodQuest[checkString(Constants.TowerType.Main)] = checkNumber(questId)
end

--- 判断是否有服务器下发的爬塔数据
function TowerQuestComponent:HasClimbTowerInfo()
    return self._hasRequestData
end

function TowerQuestComponent:StartTimeDown()
    if not isNull(self._timeDown) then
        CDTimerModule.GetInstance():RemoveCD(self._timeDown)
        self._timeDown = nil
    end
    self._timeDown = CDTimerModule.GetInstance():AddCD(1, function(count, id)
        self._hookTime = self._hookTime + 1
    end, CountDownTime, false, true)
end

function TowerQuestComponent:OverseaClimbingTowerDrawTimeHookRewardsReq(cb)
    GameUtils.Request(Interfaces.OverseaClimbingTowerDrawTimeHookRewards, { }, function(request, response)
        if checkNumber(response.errCode) ~= 0 then
            return
        end
        local jsonData = response.data

        self._hookTime = 0
        GoodsUtils.DrawRewards(jsonData.rewards)
        CS.Engine.UI.UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = { rewards = jsonData.rewards } })

        if cb then
            cb()
        end
    end)
end

function TowerQuestComponent:OverseaClimbingTowerQuestTimeHookRewardsReq(cb)
    GameUtils.Request(Interfaces.OverseaClimbingTowerQuestTimeHookRewards, { }, function(request, response)
        if checkNumber(response.errCode) ~= 0 then
            return
        end
        local jsonData = response.data

        if cb then
            cb(jsonData.rewards)
        end
    end)
end

---GetRankList
---获取排名列表
---@param towerType number
function TowerQuestComponent:GetRankList(towerType)
    local t = {}
    if self.ranking[tostring(towerType)] then
        t = checkTable(self.ranking[tostring(towerType)])
    end
    return t
end

return TowerQuestComponent